import{_ as t,o,c as i,a3 as d}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Tenant API v1 — Credit Notes","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Credit Notes | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-credit-notes"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Credit Notes | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-credit-notes"}]]},"headers":[],"relativePath":"api/tenant-v1-credit-notes.md","filePath":"api/tenant-v1-credit-notes.md","lastUpdated":1786755518000}'),s={name:"api/tenant-v1-credit-notes.md"};function a(c,e,n,r,l,p){return o(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="tenant-api-v1-—-credit-notes" tabindex="-1">Tenant API v1 — Credit Notes <a class="header-anchor" href="#tenant-api-v1-—-credit-notes" aria-label="Permalink to &quot;Tenant API v1 — Credit Notes&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:credit-notes</code>, plus permission middleware / policies.</p><blockquote><p><strong>Naming:</strong> the model is <code>CustomerCreditNote</code> — a credit note a tenant issues against <em>its own</em> customer&#39;s <code>CustomerInvoice</code>. Central&#39;s own platform-billing <code>credit_notes</code> ledger table (credits the platform issues <em>to</em> a tenant against its own subscription invoices) is unrelated.</p></blockquote><p>Requires the <strong>Invoices</strong> module (hard <code>module_dependencies</code> row) — a credit note always references a <code>CustomerInvoice</code> and cannot be created without it.</p><p>Assignee scoping: without <code>credit-notes.assign</code> (and not superadmin), list/stats/view/update/<strong>issue</strong>/<strong>apply</strong>/<strong>void</strong> only include credit notes where <code>assigned_to</code> is the current user.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-credit-notes-stats" tabindex="-1">GET <code>/credit-notes/stats</code> <a class="header-anchor" href="#get-credit-notes-stats" aria-label="Permalink to &quot;GET `/credit-notes/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Response:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;total_credit_notes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;my_credit_notes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;draft&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;issued&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;applied&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;void&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;applied_total&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;scope&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;org | mine&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>applied_total</code> sums <code>total</code> across credit notes with <code>status = applied</code>.</p><h2 id="credit-notes-crud" tabindex="-1">Credit Notes CRUD <a class="header-anchor" href="#credit-notes-crud" aria-label="Permalink to &quot;Credit Notes CRUD&quot;">​</a></h2><h3 id="get-credit-notes" tabindex="-1">GET <code>/credit-notes</code> <a class="header-anchor" href="#get-credit-notes" aria-label="Permalink to &quot;GET `/credit-notes`&quot;">​</a></h3><p>Query: <code>search</code> (matches <code>title</code> or <code>number</code>), <code>status</code> (<code>draft</code>|<code>issued</code>|<code>applied</code>|<code>void</code>), <code>customer_invoice_id</code>, <code>contact_id</code>, <code>company_id</code>, <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_credit_notes</code>, <code>trashed</code> (<code>true</code>|<code>only</code>), <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>status</code>, <code>currency</code>, <code>subtotal</code>/<code>tax_total</code>/<code>total</code>, <code>issue_date</code>, <code>customer_invoice</code> ref (<code>number</code>/<code>total</code>/<code>balance_due</code>/<code>status</code>), <code>contact</code>/<code>company</code> refs, assignee/creator refs, and <code>latest_note</code>.</p><h3 id="post-credit-notes" tabindex="-1">POST <code>/credit-notes</code> <a class="header-anchor" href="#post-credit-notes" aria-label="Permalink to &quot;POST `/credit-notes`&quot;">​</a></h3><p>Body: <code>customer_invoice_id</code> (required, tenant-scoped existence check), <code>title</code> (required), <code>notes</code>, <code>currency</code> (3-letter, optional — defaults to the linked invoice&#39;s currency when omitted), <code>issue_date</code> (optional date), <code>contact_id</code>, <code>company_id</code> (optional, module-entitlement + assignee-scope validated via <code>LinkableContact</code>/<code>LinkableCompany</code> — default to the invoice&#39;s <code>contact_id</code>/<code>company_id</code> when omitted), <code>assigned_to</code>, <code>lines</code> (array of <code>{ description, quantity, unit_price, tax_rate, sort_order }</code>).</p><p><code>subtotal</code>, <code>tax_total</code>, and <code>total</code> are computed server-side from <code>lines</code> — do not send them. Status always starts at <code>draft</code>; <code>number</code> is auto-generated (<code>CN-00001</code>, configurable via the <code>credit_notes_number_prefix</code> tenant setting). <code>number</code> is unique per tenant at the database level; on the rare concurrent-create collision, the service retries with a freshly generated number (up to 3 attempts).</p><h3 id="get-credit-notes-id" tabindex="-1">GET <code>/credit-notes/{id}</code> <a class="header-anchor" href="#get-credit-notes-id" aria-label="Permalink to &quot;GET `/credit-notes/{id}`&quot;">​</a></h3><p>Includes contact, company, the linked customer invoice, assignee, creator, lines, notes, and timeline activities.</p><h3 id="put-credit-notes-id" tabindex="-1">PUT <code>/credit-notes/{id}</code> <a class="header-anchor" href="#put-credit-notes-id" aria-label="Permalink to &quot;PUT `/credit-notes/{id}`&quot;">​</a></h3><p>Partial update of <strong>draft</strong> credit notes only — including replacing the full <code>lines</code> set (recalculates totals). Non-draft credit notes return 422 on <code>status</code> (<code>Only draft credit notes can be edited.</code>). Assignment after issuing uses <code>POST /credit-notes/{id}/assign</code>.</p><h3 id="delete-credit-notes-id" tabindex="-1">DELETE <code>/credit-notes/{id}</code> <a class="header-anchor" href="#delete-credit-notes-id" aria-label="Permalink to &quot;DELETE `/credit-notes/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>credit-notes.delete</code>.</p><h3 id="post-credit-notes-id-restore" tabindex="-1">POST <code>/credit-notes/{id}/restore</code> <a class="header-anchor" href="#post-credit-notes-id-restore" aria-label="Permalink to &quot;POST `/credit-notes/{id}/restore`&quot;">​</a></h3><p>Permission: <code>credit-notes.restore</code>.</p><h3 id="delete-credit-notes-id-force" tabindex="-1">DELETE <code>/credit-notes/{id}/force</code> <a class="header-anchor" href="#delete-credit-notes-id-force" aria-label="Permalink to &quot;DELETE `/credit-notes/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted credit note. Permission: <code>credit-notes.force.delete</code> (owner/superadmin only by default).</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-credit-notes-id-assign" tabindex="-1">POST <code>/credit-notes/{id}/assign</code> <a class="header-anchor" href="#post-credit-notes-id-assign" aria-label="Permalink to &quot;POST `/credit-notes/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><p>Permission: <code>credit-notes.assign</code>.</p><h3 id="post-credit-notes-id-issue" tabindex="-1">POST <code>/credit-notes/{id}/issue</code> <a class="header-anchor" href="#post-credit-notes-id-issue" aria-label="Permalink to &quot;POST `/credit-notes/{id}/issue`&quot;">​</a></h3><p>Transitions <code>draft → issued</code>. Backfills <code>issue_date</code> to today if unset. Permission: <code>credit-notes.issue</code>. Rejects with 422 on <code>status</code> if the credit note isn&#39;t currently <code>draft</code>.</p><h3 id="post-credit-notes-id-apply" tabindex="-1">POST <code>/credit-notes/{id}/apply</code> <a class="header-anchor" href="#post-credit-notes-id-apply" aria-label="Permalink to &quot;POST `/credit-notes/{id}/apply`&quot;">​</a></h3><p>Transitions <code>issued → applied</code>. The linked invoice is locked (<code>SELECT ... FOR UPDATE</code>) — deliberately <strong>not</strong> <code>withTrashed()</code>, so a soft-deleted invoice can never receive a credit — and validated before anything is written: rejected with a 422 on <code>status</code> if the invoice can&#39;t be found, its status is not <code>sent</code>/<code>partial</code>, or the credit note&#39;s <code>total</code> exceeds the invoice&#39;s current <code>balance_due</code> (0.01 tolerance). Once valid, adds the credit note&#39;s <code>total</code> to the invoice&#39;s <code>amount_credited</code> and calls <code>CustomerInvoice::recalculateBalanceFromAmounts()</code>, which recomputes <code>balance_due</code> <strong>and can advance the invoice <code>status</code></strong> (<code>sent → partial</code> or <code>sent → paid</code>, same as a Payment post — this is not status-neutral). Records a <code>credited</code> activity on the invoice. Permission: <code>credit-notes.apply</code>. Rejects with 422 on <code>status</code> if the credit note isn&#39;t currently <code>issued</code>.</p><h3 id="post-credit-notes-id-void" tabindex="-1">POST <code>/credit-notes/{id}/void</code> <a class="header-anchor" href="#post-credit-notes-id-void" aria-label="Permalink to &quot;POST `/credit-notes/{id}/void`&quot;">​</a></h3><p>Transitions <code>draft|issued → void</code>. Does <strong>not</strong> reverse any invoice balance — void is only valid before a credit note has been applied. Permission: <code>credit-notes.void</code>. Rejects with 422 on <code>status</code> if the credit note is already <code>applied</code> or <code>void</code>.</p><h3 id="post-credit-notes-id-notes" tabindex="-1">POST <code>/credit-notes/{id}/notes</code> <a class="header-anchor" href="#post-credit-notes-id-notes" aria-label="Permalink to &quot;POST `/credit-notes/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><p>Permission: <code>credit-notes.update</code>.</p><h3 id="get-credit-notes-id-timeline" tabindex="-1">GET <code>/credit-notes/{id}/timeline</code> <a class="header-anchor" href="#get-credit-notes-id-timeline" aria-label="Permalink to &quot;GET `/credit-notes/{id}/timeline`&quot;">​</a></h3><p>Domain timeline entries (<code>created</code>, <code>updated</code>, <code>assigned</code>, <code>status_changed</code>, <code>issued</code>, <code>applied</code>, <code>voided</code>, <code>note_added</code>, <code>deleted</code>, <code>restored</code>).</p>',43)])])}const k=t(s,[["render",a]]);export{u as __pageData,k as default};
